/**
 * Per-prefix ordinary fallback wrapper: the factorized owner retains the shared compiled filter across suffix opens.
 */
@Experimental
final class SuffixFilterCursor implements RowCursor {
	final RowCursor arg;
	final NativeBooleanFilter filter;
	final RowState row;

	SuffixFilterCursor(RowCursor arg, NativeBooleanFilter filter, RowState row) {
		this.arg = arg;
		this.filter = filter;
		this.row = row;
	}

	@Override
	public boolean next() throws IOException {
		while (arg.next()) {
			if (filter.accept(row)) {
				return true;
			}
		}
		return false;
	}

	@Override
	public void close() {
		// mirror FilterCursor: the filter may hold lazily acquired native resources (an EXISTS witness's
		// semijoin probe pins a dataset read stamp), and the cursor that ran it owns their release
		Throwable failure = null;
		try {
			arg.close();
		} catch (RuntimeException | Error problem) {
			failure = problem;
		}
		try {
			filter.close();
		} catch (RuntimeException | Error problem) {
			if (failure == null) {
				failure = problem;
			} else if (failure != problem) {
				failure.addSuppressed(problem);
			}
		}
		if (failure instanceof Error) {
			throw (Error) failure;
		}
		if (failure != null) {
			throw (RuntimeException) failure;
		}
	}
}

@Experimental
final class LateralPlan implements SlotPlan {
	final SlotPlan left;
	final SlotPlan right;
	final long rightInputMask;
	final long producedMask;

	LateralPlan(SlotPlan left, SlotPlan right, long rightInputMask) {
		this.left = left;
		this.right = right;
		this.rightInputMask = rightInputMask;
		this.producedMask = left.producedMask() | right.producedMask();
	}

	@Override
	public RowCursor open(RowState row) throws IOException {
		long entryMask = row.boundMask();
		return new LateralCursor(left.open(row), right, rightInputMask | entryMask, row);
	}

	@Override
	public BatchCursor openBatch(RowState row, int capacity) throws IOException {
		if (right instanceof PatternPlan pattern) {
			BatchCursor wildcard = LmdbWildcardPredicateBatch.tryOpenLateral(left, pattern, rightInputMask, row,
					capacity);
			if (wildcard != null) {
				return wildcard;
			}
		}
		BatchCursor batch = left.openBatch(row, capacity);
		if (batch == null) {
			return null;
		}
		RowCursor rows = LmdbWildcardPredicateBatch.asRows(batch, row, capacity);
		return rows == null ? null
				: new RowBatchCursor(new LateralCursor(rows, right, rightInputMask | row.boundMask(), row), row);
	}

	@Override
	public LmdbNativeWork estimateWork(RowState row, long boundMask) {
		return LmdbNativeWork.probeChain(left, right, row, boundMask);
	}

	@Override
	public double estimateRows(RowState row, long boundMask) {
		double leftRows = LmdbNativeWork.rowsOut(left, row, boundMask);
		double rightRows = LmdbNativeWork.rowsOut(right, row, boundMask | rightInputMask);
		if (Double.isNaN(leftRows) || Double.isNaN(rightRows)) {
			return Double.NaN;
		}
		double rows = leftRows * rightRows;
		return Double.isFinite(rows) ? rows : Double.NaN;
	}

	@Override
	public long producedMask() {
		return producedMask;
	}
}

/**
 * Non-reorderable correlated LATERAL cursor. Bindings present at operator entry remain visible to the right arm;
 * bindings added by the left arm are visible only when declared in {@code rightInputBindingNames}. Hidden left values
 * are restored before each merged row is exposed and before control returns to the outer plan.
 */
@Experimental
final class LateralCursor implements FactorizedRowCursor {
	private final RowCursor left;
	private final SlotPlan rightPlan;
	private final long visibleInputMask;
	private final RowState row;
	private final int[] hiddenSlots;
	private final long[] hiddenValues;
	private RowCursor right;
	private int hiddenCount;
	private long rightLexicalInputMask;
	private boolean leftHidden;
	private boolean closed;
	private int pollTick;

	LateralCursor(RowCursor left, SlotPlan rightPlan, long visibleInputMask, RowState row) {
		this.left = left;
		this.rightPlan = rightPlan;
		this.visibleInputMask = visibleInputMask;
		this.row = row;
		this.hiddenSlots = new int[row.slots.length];
		this.hiddenValues = new long[row.slots.length];
	}

	@Override
	public boolean next() throws IOException {
		if (closed || row.cancellation.isCancellationRequested()) {
			return false;
		}
		while (true) {
			LmdbNativeProbeDeadline.poll(++pollTick);
			if (right != null) {
				hideLeftBindings();
				long previousScope = row.enterLexicalScope(rightLexicalInputMask);
				boolean available;
				try {
					available = right.next();
				} finally {
					row.restoreLexicalScope(previousScope);
					restoreLeftBindings();
				}
				if (available) {
					return true;
				}
				right.close();
				right = null;
			}
			if (!left.next()) {
				close();
				return false;
			}
			captureAndHideLeftBindings();
			rightLexicalInputMask = row.boundMask();
			long previousScope = row.enterLexicalScope(rightLexicalInputMask);
			try {
				right = rightPlan.open(row);
			} finally {
				row.restoreLexicalScope(previousScope);
				restoreLeftBindings();
			}
		}
	}

	private void captureAndHideLeftBindings() {
		hiddenCount = 0;
		long hiddenMask = row.boundMask() & ~visibleInputMask;
		while (hiddenMask != 0L) {
			int slot = Long.numberOfTrailingZeros(hiddenMask);
			hiddenMask &= hiddenMask - 1L;
			hiddenSlots[hiddenCount] = slot;
			hiddenValues[hiddenCount] = row.slots[slot];
			hiddenCount++;
		}
		hideLeftBindings();
	}

	private void hideLeftBindings() {
		if (leftHidden) {
			return;
		}
		for (int i = 0; i < hiddenCount; i++) {
			row.replaceSlot(hiddenSlots[i], UNKNOWN);
		}
		leftHidden = true;
	}

	private void restoreLeftBindings() {
		if (!leftHidden) {
			return;
		}
		for (int i = 0; i < hiddenCount; i++) {
			row.replaceSlot(hiddenSlots[i], hiddenValues[i]);
		}
		leftHidden = false;
	}

	@Override
	public void close() {
		if (closed) {
			return;
		}
		closed = true;
		Throwable failure = null;
		try {
			if (right != null) {
				right.close();
			}
		} catch (RuntimeException | Error problem) {
			failure = problem;
		}
		try {
			left.close();
		} catch (RuntimeException | Error problem) {
			if (failure == null) {
				failure = problem;
			} else if (failure != problem) {
				failure.addSuppressed(problem);
			}
		} finally {
			restoreLeftBindings();
		}
		if (failure instanceof RuntimeException runtimeException) {
			throw runtimeException;
		}
		if (failure instanceof Error error) {
			throw error;
		}
	}

	@Override
	public long multiplicity() {
		long leftMultiplicity = left instanceof FactorizedRowCursor factorized ? factorized.multiplicity() : 1L;
		long rightMultiplicity = right instanceof FactorizedRowCursor factorized ? factorized.multiplicity() : 1L;
		return Math.multiplyExact(leftMultiplicity, rightMultiplicity);
	}
}

@Experimental
final class JoinPlan implements SlotPlan {
	final SlotPlan left;
	final SlotPlan right;
	final long producedMask;

	JoinPlan(SlotPlan left, SlotPlan right) {
		this.left = left;
		this.right = right;
		this.producedMask = left.producedMask() | right.producedMask();
	}

	@Override
	public LmdbNativeWork estimateWork(RowState row, long boundMask) {
		return LmdbNativeWork.probeChain(left, right, row, boundMask);
	}

	@Override
	public double estimateRows(RowState row, long boundMask) {
		double leftRows = LmdbNativeWork.rowsOut(left, row, boundMask);
		if (Double.isNaN(leftRows)) {
			return Double.NaN;
		}
		// The right side is evaluated with the left's slots bound, so its estimate is already per probe.
		double rightPerProbe = LmdbNativeWork.rowsOut(right, row, boundMask | left.producedMask());
		if (Double.isNaN(rightPerProbe)) {
			return Double.NaN;
		}
		double rows = leftRows * rightPerProbe;
		return Double.isFinite(rows) ? rows : Double.NaN;
	}

	@Override
	public RowCursor open(RowState row) throws IOException {
		PathTargetSet targets = PathTargetSet.tryCreate(left, right, row);
		try {
			return open(row, targets, targets != null);
		} catch (IOException | RuntimeException | Error problem) {
			if (targets != null) {
				targets.close();
			}
			throw problem;
		}
	}

	@Override
	public BatchCursor openBatch(RowState row, int capacity) throws IOException {
		if (right instanceof PatternPlan pattern) {
			BatchCursor wildcard = LmdbWildcardPredicateBatch.tryOpenPayload(left, pattern, row, capacity);
			if (wildcard != null) {
				return wildcard;
			}
		}
		// Bushy runtime build (three-tier parity ExecPlan M6): a pattern beside a sub-plan whose sweep is
		// input-independent drains the sub-plan once into the primitive hash table instead of nested-looping it.
		BatchCursor bushy = LmdbNativeHashJoin.tryOpenBushy(this, row, capacity);
		if (bushy != null) {
			return bushy;
		}
		BatchCursor leftBatch = left.openBatch(row, capacity);
		if (leftBatch == null) {
			return null;
		}
		RowCursor leftRows = LmdbWildcardPredicateBatch.asRows(leftBatch, row, capacity);
		return leftRows == null ? null
				: new RowBatchCursor(new JoinCursor(leftRows, right, row, left.producedMask()), row);
	}

	RowCursor open(RowState row, PathTargetSet targets, boolean ownsTargets) throws IOException {
		double expectedProbes = Double.NaN;
		double perProbeRows = Double.NaN;
		double sweepEstimate = Double.NaN;
		if (RightMemoProbe.sweepEnabled()) {
			long boundMask = row.boundMask();
			expectedProbes = LmdbNativeWork.rowsOut(left, row, boundMask);
			perProbeRows = RightMemoProbe.fragmentRowsForMask(right, row, boundMask | left.producedMask());
			// correlated slots are unbound at open time, so this estimates the key-unbound fragment sweep
			sweepEstimate = LmdbNativeWork.rowsOut(right, row, boundMask);
		}
		// only left-produced slots vary across left rows; slots bound at open time are constant for
		// the lifetime of this cursor and do not disqualify replay
		RowCursor leftCursor = openWithTargets(left, row, targets);
		try {
			return new JoinCursor(leftCursor, right, row, left.producedMask(), targets, ownsTargets,
					expectedProbes, perProbeRows, sweepEstimate);
		} catch (RuntimeException | Error problem) {
			leftCursor.close();
			throw problem;
		}
	}

	static RowCursor openWithTargets(SlotPlan plan, RowState row, PathTargetSet targets) throws IOException {
		if (targets == null || !targets.appliesTo(plan)) {
			return plan.open(row);
		}
		if (plan == targets.path) {
			return targets.path.open(row, null, null, targets);
		}
		if (plan instanceof JoinPlan) {
			return ((JoinPlan) plan).open(row, targets, false);
		}
		FilterPlan filter = (FilterPlan) plan;
		return new FilterCursor(openWithTargets(filter.arg, row, targets), filter.filter, row);
	}

	@Override
	public long producedMask() {
		return producedMask;
	}
}

@Experimental
final class JoinCursor implements FactorizedRowCursor {
	/** Abandon materialization beyond this many rows and fall back to re-opening the right side per left row. */
	static final int MAX_MATERIALIZED_ROWS = 1 << 16;
	static final int SCALAR_PATTERN_ROWS = 2;
	static final int PATTERN_BATCH_ROWS = 256;

	final RowCursor leftCursor;
	final SlotPlan right;
	final RowState row;
	final PathTargetSet pathTargets;
	final boolean ownsPathTargets;
	private int probePollTick;
	RowCursor rightCursor;
	/**
	 * When the right side reads no slot produced by the left side (and its reads are fully known, see
	 * {@link #memoReadMask}), its row stream is identical for every left row: it is scanned once while serving the
	 * first left row and replayed from memory afterwards, instead of re-running the LMDB probes per left row. Non-null
	 * replaySlots marks the right side as replayable; they list the slots the replay re-binds.
	 */
	final int[] replaySlots;
	/**
	 * Milestone 4 (three-tier parity ExecPlan): estimate-triggered key-unbound sweep for a CORRELATED right fragment —
	 * the inner twin of the {@code LeftJoinCursor} sweep. Non-null only when the sweep flag is on and the left-side row
	 * estimate justifies one fragment sweep over per-row re-execution.
	 */
	final RightMemoProbe rightMemo;
	NativeLmdbQuerySource.NativeProbe rightProbe;
	PathResultMemo pathMemo;
	boolean pathMemoInitialized;
	/** Reused for the common correlated PatternPlan right side. Binding/batching lives in this cursor too. */
	final PatternPlan patternRight;
	PatternCursor patternCursor;
	boolean patternRightActive;
	LmdbAdaptiveLongArray patternBatchMemory;
	int patternBatchCapacityRows;
	int patternBatchRows;
	int patternBatchPosition;
	int patternScalarRows;
	boolean patternBatchRefused;
	int patternMark = -1;
	/** Query-budgeted flat row-major replay storage: no object per captured right row. */
	LmdbAdaptiveLongArray replayMemory;
	int replayRows;
	boolean capturingReplay;
	boolean replayDisabled;
	boolean rightMaterialized;
	int replayIndex = -1;
	int replayMark = -1;

	JoinCursor(RowCursor leftCursor, SlotPlan right, RowState row, long leftProducedMask) {
		this(leftCursor, right, row, leftProducedMask, null, false, Double.NaN, Double.NaN, Double.NaN);
	}

	JoinCursor(RowCursor leftCursor, SlotPlan right, RowState row, long leftProducedMask,
			PathTargetSet pathTargets, boolean ownsPathTargets, double expectedProbes, double perProbeRows,
			double sweepEstimate) {
		this.leftCursor = leftCursor;
		this.right = right;
		this.row = row;
		this.pathTargets = pathTargets;
		this.ownsPathTargets = ownsPathTargets;
		this.patternRight = right instanceof PatternPlan pattern ? pattern : null;
		long readMask = memoReadMask(right);
		this.replaySlots = readMask >= 0L && (readMask & leftProducedMask) == 0L
				? slotsOf(right.producedMask())
				: null;
		this.rightMemo = replaySlots == null
				? RightMemoProbe.tryCreateSweepOnly(right, leftProducedMask, readMask, row, expectedProbes,
						perProbeRows, sweepEstimate)
				: null;
	}

	@Override
	public long multiplicity() {
		long leftMultiplicity = leftCursor instanceof FactorizedRowCursor factorized
				? factorized.multiplicity()
				: 1L;
		long rightMultiplicity = rightCursor instanceof FactorizedRowCursor factorized
				? factorized.multiplicity()
				: 1L;
		return Math.multiplyExact(leftMultiplicity, rightMultiplicity);
	}

	@Override
	public boolean next() throws IOException {
		if (rightMaterialized) {
			return replayNext();
		}
		while (true) {
			// A long run of left rows with empty right sides spins here without emitting; the consumer's per-row
			// polls never fire then, so this loop needs its own poll point (M0 poll-coverage pattern).
			LmdbNativeProbeDeadline.poll(++probePollTick);
			if (patternRightActive) {
				if (nextPatternRight()) {
					if (capturingReplay) {
						recordReplay();
					}
					return true;
				}
				closePatternRight();
				if (finishCapturedRight()) {
					return replayNext();
				}
			} else if (rightCursor != null) {
				if (rightCursor.next()) {
					if (capturingReplay) {
						recordReplay();
					}
					return true;
				}
				closeRight();
				if (finishCapturedRight()) {
					return replayNext();
				}
			}
			if (!leftCursor.next()) {
				return false;
			}
			rightCursor = openRight();
			if (replaySlots != null && !rightMaterialized && !replayDisabled) {
				capturingReplay = true;
			}
		}
	}

	RowCursor openRight() throws IOException {
		if (pathTargets != null && pathTargets.appliesTo(right)) {
			if (right == pathTargets.path) {
				if (rightProbe == null) {
					rightProbe = row.source.newProbe();
				}
				return pathTargets.path.open(row, rightProbe, null, pathTargets);
			}
			return JoinPlan.openWithTargets(right, row, pathTargets);
		}
		if (patternRight != null || right instanceof PathPlan) {
			if (rightProbe == null) {
				rightProbe = row.source.newProbe();
			}
			if (patternRight != null) {
				if (patternCursor == null) {
					patternCursor = new PatternCursor();
				}
				PatternCursor raw = patternRight.openRaw(row, rightProbe, patternCursor);
				if (raw == PatternCursor.EMPTY) {
					return EmptyCursor.INSTANCE;
				}
				patternRightActive = true;
				patternBatchRows = 0;
				patternBatchPosition = 0;
				patternScalarRows = 0;
				return null;
			}
			if (!pathMemoInitialized) {
				pathMemo = replaySlots == null ? PathResultMemo.tryCreate((PathPlan) right, row) : null;
				pathMemoInitialized = true;
			}
			return ((PathPlan) right).open(row, rightProbe, pathMemo);
		}
		if (rightMemo != null) {
			RowCursor memoized = rightMemo.open(row);
			if (memoized != null) {
				return memoized;
			}
		}
		return right.open(row);
	}

	private boolean finishCapturedRight() {
		if (!capturingReplay) {
			return false;
		}
		// The first right stream is now fully captured. Replay starts with the next left row.
		capturingReplay = false;
		rightMaterialized = true;
		replayIndex = -1;
		return true;
	}

	private boolean nextPatternRight() throws IOException {
		releasePatternBinding();
		while (true) {
			if (patternBatchMemory != null) {
				long[] patternBatch = patternBatchMemory.values();
				if (patternBatchPosition >= patternBatchRows) {
					patternBatchRows = patternCursor.fill(patternBatch, patternBatchCapacityRows);
					patternBatchPosition = 0;
					if (patternBatchRows == 0) {
						return false;
					}
				}
				int offset = patternBatchPosition++ << 2;
				if (bindPattern(patternBatch, offset)) {
					return true;
				}
				continue;
			}
			long[] quad = patternCursor.next();
			if (quad == null) {
				return false;
			}
			if (++patternScalarRows > SCALAR_PATTERN_ROWS && !patternBatchRefused) {
				tryEnablePatternBatch();
			}
			if (bindPattern(quad, 0)) {
				return true;
			}
		}
	}

	private void tryEnablePatternBatch() {
		LmdbAdaptiveLongArray memory = LmdbAdaptiveLongArray.tryCreate(row, PATTERN_BATCH_ROWS * 4);
		int rows = PATTERN_BATCH_ROWS;
		if (memory == null) {
			rows = 64;
			memory = LmdbAdaptiveLongArray.tryCreate(row, rows * 4);
		}
		if (memory == null) {
			patternBatchRefused = true;
			return;
		}
		patternBatchMemory = memory;
		patternBatchCapacityRows = rows;
	}

	private boolean bindPattern(long[] quad, int offset) {
		int mark = row.mark();
		if (patternRight.bind(quad, offset, row)) {
			patternMark = mark;
			return true;
		}
		row.rollback(mark);
		return false;
	}

	private void releasePatternBinding() {
		if (patternMark >= 0) {
			row.rollback(patternMark);
			patternMark = -1;
		}
	}

	private void closePatternRight() {
		releasePatternBinding();
		patternCursor.close();
		patternRightActive = false;
		patternBatchRows = 0;
		patternBatchPosition = 0;
	}

	boolean replayNext() throws IOException {
		while (true) {
			if (replayIndex >= 0) {
				releaseReplay();
				while (replayIndex < replayRows) {
					int rowIndex = replayIndex++;
					int mark = row.mark();
					if (bindReplay(rowIndex)) {
						replayMark = mark;
						return true;
					}
					row.rollback(mark);
				}
				replayIndex = -1;
			}
			if (!leftCursor.next()) {
				return false;
			}
			replayIndex = 0;
		}
	}

	boolean bindReplay(int rowIndex) {
		int width = replaySlots.length;
		if (width == 0) {
			return true;
		}
		int offset = rowIndex * width;
		long[] replayValues = replayMemory.values();
		for (int i = 0; i < replaySlots.length; i++) {
			long value = replayValues[offset + i];
			if (value != UNKNOWN && !row.bind(replaySlots[i], value)) {
				return false;
			}
		}
		return true;
	}

	void recordReplay() {
		if (replayRows >= MAX_MATERIALIZED_ROWS) {
			disableReplay();
			return;
		}
		int width = replaySlots.length;
		if (width != 0) {
			if (!ensureReplayCapacity(replayRows + 1, width)) {
				disableReplay();
				return;
			}
			long[] replayValues = replayMemory.values();
			int offset = replayRows * width;
			for (int i = 0; i < width; i++) {
				replayValues[offset + i] = row.slots[replaySlots[i]];
			}
		}
		replayRows++;
	}

	private boolean ensureReplayCapacity(int requiredRows, int width) {
		int required = Math.multiplyExact(requiredRows, width);
		if (replayMemory != null && replayMemory.length() >= required) {
			return true;
		}
		int currentRows = replayMemory == null ? 0 : replayMemory.length() / width;
		int grownRows = currentRows == 0 ? Math.min(16, MAX_MATERIALIZED_ROWS)
				: Math.min(MAX_MATERIALIZED_ROWS, currentRows << 1);
		if (grownRows < requiredRows) {
			grownRows = requiredRows;
		}
		int grownLength = Math.multiplyExact(grownRows, width);
		if (replayMemory == null) {
			replayMemory = LmdbAdaptiveLongArray.tryCreate(row, grownLength);
			return replayMemory != null;
		}
		return replayMemory.ensureCapacity(grownLength);
	}

	private void disableReplay() {
		capturingReplay = false;
		replayDisabled = true;
		if (replayMemory != null) {
			replayMemory.close();
			replayMemory = null;
		}
		replayRows = 0;
	}

	void releaseReplay() {
		if (replayMark >= 0) {
			row.rollback(replayMark);
			replayMark = -1;
		}
	}

	@Override
	public void close() {
		releaseReplay();
		closeRight();
		if (pathMemo != null) {
			pathMemo.close();
			pathMemo = null;
		}
		if (rightMemo != null) {
			rightMemo.close();
		}
		if (rightProbe != null) {
			rightProbe.close();
			rightProbe = null;
		}
		if (patternBatchMemory != null) {
			patternBatchMemory.close();
			patternBatchMemory = null;
		}
		if (replayMemory != null) {
			replayMemory.close();
			replayMemory = null;
		}
		try {
			leftCursor.close();
		} finally {
			if (ownsPathTargets) {
				pathTargets.close();
			}
		}
	}

	void closeRight() {
		if (patternRightActive) {
			closePatternRight();
		}
		if (rightCursor != null) {
			rightCursor.close();
			rightCursor = null;
		}
	}
}
